<?php if(!$news): ?><div class="empty-editorial"><span class="eyebrow">ESTAMOS EN CONTACTO</span><h3>Las novedades del equipo tendrán su lugar aquí.</h3><p>Consulta este espacio para conocer las próximas publicaciones de la academia.</p></div><?php else: ?><div class="publication-grid"><?php foreach($news as $index=>$item): ?><article class="publication-card"><div class="publication-art <?= $item['tipo']==='actividad'?'activity-art':'' ?>" aria-hidden="true"><span class="art-circle"></span><span class="art-line"></span><span class="art-word"><?= $item['tipo']==='actividad'?'EN EQUIPO':'AL DÍA' ?></span></div><div class="publication-body"><div class="publication-meta"><span class="badge"><?= e(ucfirst($item['tipo'])) ?></span><time datetime="<?= e($item['fecha']) ?>"><?= e(date('d/m/Y',strtotime($item['fecha']))) ?></time></div><h3><a href="<?= e(url('publicacion',['id'=>$item['id']])) ?>"><?= e($item['titulo']) ?></a></h3><p><?= e(mb_strimwidth($item['contenido'],0,180,'…','UTF-8')) ?></p><a class="text-link" href="<?= e(url('publicacion',['id'=>$item['id']])) ?>" aria-label="Leer <?= e($item['titulo']) ?>">Leer publicación</a></div></article><?php endforeach; ?></div><?php endif; ?>
